<?php
declare(strict_types=1);
function db(): PDO {
    global $config;
    static $pdo;
    return $pdo ??= new PDO($config['dsn'], $config['db_user'], $config['db_password'], [PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION, PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC, PDO::ATTR_EMULATE_PREPARES=>false, PDO::MYSQL_ATTR_INIT_COMMAND=>"SET time_zone = '".date('P')."'"]);
}
function query(string $sql, array $params=[]): PDOStatement { $q=db()->prepare($sql); $q->execute($params); return $q; }
function rows(string $sql, array $params=[]): array { return query($sql,$params)->fetchAll(); }
function one(string $sql, array $params=[]): ?array { return query($sql,$params)->fetch() ?: null; }
function scalar(string $sql, array $params=[]): mixed { return query($sql,$params)->fetchColumn(); }
function e(mixed $value): string { return htmlspecialchars((string)($value ?? ''), ENT_QUOTES|ENT_SUBSTITUTE, 'UTF-8'); }
function redirect(string $path): never { header('Location: '.$path); exit; }
function bid(): int { return (int)current_user()['business_id']; }
function csrf(): string { return $_SESSION['csrf'] ??= bin2hex(random_bytes(32)); }
function csrf_field(): void { echo '<input type="hidden" name="csrf" value="'.e(csrf()).'">'; }
function verify_csrf(): void { if (!hash_equals(csrf(), (string)($_POST['csrf']??''))) { http_response_code(419); exit('This form expired. Reload the page and try again.'); } }
function flash(string $message,string $type='success'): void { $_SESSION['flash']=['message'=>$message,'type'=>$type]; }
function audit(string $action,string $entity='',?int $id=null,array $details=[]): void { query('INSERT INTO activity_logs (business_id,user_id,action,entity,entity_id,details) VALUES (?,?,?,?,?,?)',[bid(),current_user()['id'],$action,$entity,$id,json_encode($details,JSON_THROW_ON_ERROR)]); }
function transaction(callable $fn): mixed { if(db()->inTransaction()) return $fn(); db()->beginTransaction(); try { $result=$fn(); db()->commit(); return $result; } catch(Throwable $e) { if(db()->inTransaction()) db()->rollBack(); throw $e; } }
function business(): array { static $b; return $b ??= one('SELECT * FROM businesses WHERE id=?',[bid()]); }
function profile(): array { return json_decode(business()['profile'],true); }
function setting(string $key,mixed $fallback=null): mixed { $v=scalar('SELECT value FROM business_settings WHERE business_id=? AND setting_key=?',[bid(),$key]); return $v===false ? $fallback : json_decode($v,true); }
function save_setting(string $key,mixed $value): void { query('INSERT INTO business_settings (business_id,setting_key,value) VALUES (?,?,?) ON DUPLICATE KEY UPDATE value=VALUES(value)',[bid(),$key,json_encode($value,JSON_THROW_ON_ERROR)]); }
function money(mixed $value,bool $symbol=true): string { $n=number_format((float)$value,2,'.',''); [$a,$b]=explode('.',$n); $sign=str_starts_with($a,'-')?'-':''; $a=ltrim($a,'-'); if(strlen($a)>3) $a=preg_replace('/\B(?=(\d{2})+(?!\d))/',',',substr($a,0,-3)).','.substr($a,-3); return ($symbol?'₹':'').$sign.$a.'.'.$b; }
function date_label(?string $date): string { return $date ? date('d M Y',strtotime($date)) : '—'; }
function required_text(string $key,int $max=160): string { $s=trim((string)($_POST[$key]??'')); if($s===''||mb_strlen($s)>$max) throw new DomainException('Please enter a valid '.str_replace('_',' ',$key).'.'); return $s; }
function valid_date(string $value): string { $d=DateTimeImmutable::createFromFormat('!Y-m-d',$value); if(!$d||$d->format('Y-m-d')!==$value) throw new DomainException('Please enter a valid date.'); return $value; }
function badge(string $status): string { $style=match($status){'Paid','Won','Completed','Active','Accepted'=>'green','Overdue','Lost','Void','Cancelled'=>'red','Partially Paid','Pending','Sent','Qualified'=>'amber','Issued','In Progress','Proposal'=>'blue',default=>'neutral'}; return '<span class="badge '.$style.'"><span></span>'.e($status).'</span>'; }
function initials(string $name): string { $p=preg_split('/\s+/',trim($name)); return mb_strtoupper(mb_substr($p[0],0,1).mb_substr($p[1]??'',0,1)); }
function icon(string $name,string $class=''): string { $allowed=['layout-dashboard','users','target-arrow','package','checkbox','file-description','file-invoice','credit-card','receipt','chart-bar','sparkles','settings','chevron-down','chevron-right','chevron-left','arrow-up-right','arrow-down-right','plus','search','bell','sun','moon','menu-2','logout','download','dots','arrow-right','x','check','mail','phone','building','calendar','filter','arrow-up','arrow-down','help-circle','shield-check','database','refresh','eye','printer','external-link','arrow-left','clock','circle-check','wallet','trending-up','chart-pie','circle','device-floppy','send','file-export','adjustments-horizontal']; return '<svg class="icon '.e($class).'" aria-hidden="true"><use href="assets/icons/tabler.svg#'.(in_array($name,$allowed,true)?$name:'circle').'"></use></svg>'; }
function period(): array { $preset=$_GET['period']??'month'; $today=new DateTimeImmutable('today'); [$start,$end]=match($preset){'today'=>[$today,$today],'yesterday'=>[$today->modify('-1 day'),$today->modify('-1 day')],'7days'=>[$today->modify('-6 days'),$today],'30days'=>[$today->modify('-29 days'),$today],'previous'=>[$today->modify('first day of last month'),$today->modify('last day of last month')],'quarter'=>[$today->setDate((int)$today->format('Y'),(int)(floor(((int)$today->format('n')-1)/3)*3+1),1),$today],'year'=>[$today->modify('first day of January'),$today],'previous_year'=>[$today->modify('-1 year')->modify('first day of January'),$today->modify('-1 year')->modify('last day of December')],'all'=>[new DateTimeImmutable('2000-01-01'),$today->modify('+10 years')],default=>[$today->modify('first day of this month'),$today]}; if($preset==='custom') { $start=new DateTimeImmutable(valid_date((string)($_GET['from']??$today->format('Y-m-d')))); $end=new DateTimeImmutable(valid_date((string)($_GET['to']??$today->format('Y-m-d')))); if($end<$start || $end->diff($start)->days>3660) throw new DomainException('Choose a date range of up to ten years.'); } return [$start->format('Y-m-d'),$end->format('Y-m-d')]; }
function period_select(): void { $options=['today'=>'Today','yesterday'=>'Yesterday','7days'=>'Last 7 days','30days'=>'Last 30 days','month'=>'This month','previous'=>'Previous month','quarter'=>'This quarter','year'=>'This year','previous_year'=>'Previous year','all'=>'All time','custom'=>'Custom range']; echo '<select name="period" aria-label="Date period" data-auto-submit>'; foreach($options as $v=>$label) echo '<option value="'.$v.'" '.(($_GET['period']??'month')===$v?'selected':'').'>'.$label.'</option>'; echo '</select>'; if(($_GET['period']??'')==='custom') echo '<input type="date" name="from" value="'.e($_GET['from']??date('Y-m-01')).'" aria-label="Start date"><input type="date" name="to" value="'.e($_GET['to']??date('Y-m-d')).'" aria-label="End date"><button class="btn">Apply</button>'; }
